/* ---------------- DrawStopZone (src/pilot/DrawStopZone.c) ---------------- */
/* Driver 2: DrawStopZone (TARGETS.C) */
extern int current;
#define current (*(DB **)&current)
extern volatile int CameraCnt;
#define CameraCnt (*(volatile int *)&CameraCnt)
void DrawStopZone(VECTOR *pPosition)
{
    VECTOR pStopZonePt[4] = {
        {-500, 0, 500},
        {500, 0, 500},
        {-500, 0, -500},
        {500, 0, -500},
    };
    SVECTOR temp;
    long p;
    long flag;
    int sz;
    VECTOR *pVector;
    POLY_FT4 *pPoly;
    int *pOut;

    gte_SetRotMatrix(&D_000B8FE8);
    gte_SetTransVec0(&D_0008909C);

    pVector = pStopZonePt;
    pPoly = (POLY_FT4 *)current->primptr;
    setPolyFT4(pPoly);
    pOut = (int *)&pPoly->x0;

    while (pVector < &pStopZonePt[4]) {
        pVector->vx = pVector->vx * (-CameraCnt % 16) / 16;
        pVector->vz = pVector->vz * (-CameraCnt % 16) / 16;
        pVector->vx += pPosition->vx;
        pVector->vz += pPosition->vz;
        pVector->vy = -MapHeight(pVector);
        pVector->vx -= camera_position.vx;
        pVector->vy -= camera_position.vy;
        pVector->vz -= camera_position.vz;
        func_0002C564(pVector);
        temp.vx = pVector->vx;
        temp.vy = pVector->vy;
        temp.vz = pVector->vz;
        RotTransPers(&temp, pOut, &p, &flag);

        if (pOut == (int *)&pPoly->x0)
            pOut = (int *)&pPoly->x1;
        else if (pOut == (int *)&pPoly->x1)
            pOut = (int *)&pPoly->x2;
        else
            pOut = (int *)&pPoly->x3;

        pVector++;
    }

    gte_stsz(&sz);

    pPoly->r0 = 64;
    pPoly->g0 = 64;
    pPoly->b0 = 64;
    setSemiTrans(pPoly, 1);

    pPoly->u0 = D_000B9170.u0;
    pPoly->v0 = D_000B9170.v0;
    pPoly->u1 = D_000B9170.u1;
    pPoly->v1 = D_000B9170.v1;
    pPoly->u2 = D_000B9170.u2;
    pPoly->v2 = D_000B9170.v2;
    pPoly->u3 = D_000B9170.u3;
    pPoly->v3 = D_000B9170.v3;

    if (*(int *)&gNight)
        pPoly->tpage = D_000B9170.tpage | 0x20;
    else
        pPoly->tpage = D_000B9170.tpage | 0x40;

    pPoly->clut = D_000B917A[0];

    addPrim(current->ot + (sz >> 4) + 512, pPoly);

    current->primptr += sizeof(POLY_FT4);
}
#undef CameraCnt
#undef current

